SELECT COUNT(*) AS total
FROM homework h


        AND h.creator = #{userId}


        AND h.class_id = #{classId}

SELECT c.class_name AS className, u.user_name AS userName, co.course_name AS courseName, , COALESCE(udh_submitted.submitted_count, 0) AS submittedCount, COALESCE(uc_total.total_count, 0) AS totalCount FROM homework h LEFT JOIN class c ON c.id = h.class_id LEFT JOIN course co ON co.id = c.course_id LEFT JOIN `user` u ON u.id = h.creator LEFT JOIN ( SELECT homework_id, COUNT(*) AS submitted_count FROM user_do_homework GROUP BY homework_id ) udh_submitted ON h.id = udh_submitted.homework_id LEFT JOIN ( SELECT class_id, COUNT(*) AS total_count FROM user_class GROUP BY class_id ) uc_total ON h.class_id = uc_total.class_id
AND h.creator = #{userId}
AND h.class_id = #{classId}
ORDER BY h.id DESC LIMIT #{page},#{pageSize}

SELECT c.class_name AS className, u.user_name AS userName, co.course_name AS courseName,
FROM homework h LEFT JOIN class c ON c.id = h.class_id LEFT JOIN course co ON co.id = c.course_id LEFT JOIN `user` u ON u.id = h.creator LEFT JOIN user_do_homework udh ON h.id = udh.homework_id AND udh.user_id = #{userId}
AND (udh.id IS NULL OR udh.mode = '2')
AND h.class_id = #{classId}
ORDER BY h.id DESC LIMIT #{page},#{pageSize}

SELECT COUNT(*) AS total
FROM homework h
LEFT JOIN user_do_homework udh ON h.id = udh.homework_id AND udh.user_id = #{userId}

    AND (udh.id IS NULL OR udh.mode = '2')

        AND h.class_id = #{classId}
